\begin{lem}
\ollabel{lem:fseq-init}
Suppose that $\tuple{!A_0,\dotsc,!A_n}$ is a formation sequence
for~$!A_n$, and that $k \leq n$. Then $\tuple{!A_0,\dotsc,!A_k}$
is a formation sequence for~$!A_k$.
\end{lem}

