\item \ollabel{def:Cut} تعدی: اگر $\Gamma \Entails !A$ و
  $\Delta \cup \{ !A\} \Entails !B$، آنگاه $\Gamma \cup \Delta \Entails
  !B$ برقرار است.
\end{enumerate}
\end{prop}

